long long powerMod(long long base, long long exp, long long mod) {
    long long res = 1;
    base %= mod;
    while (exp > 0) {
        if (exp % 2 == 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp /= 2;
    }
    return res;
}

int main() {
    cout << "3^13 mod 1000 = " << powerMod(3, 13, 1000) << endl; // In ra: 403
    return 0;
}

#include <iostream>
