void bfs(int start, const vector<vector<int>>& adj) {
    vector<bool> visited(adj.size(), false);
    queue<int> q;
    q.push(start); visited[start] = true;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        cout << u << " ";
        for (int v : adj[u]) {
            if (!visited[v]) { visited[v] = true; q.push(v); }
        }
    }
    cout << endl;
}

int main() {
    vector<vector<int>> adj(4);
    adj[0] = {1, 2}; adj[1] = {2}; adj[2] = {0, 3}; adj[3] = {3};
    bfs(2, adj); // Duyet BFS bat dau tu dinh 2
    return 0;
}

#include <iostream>
#include <vector>
#include <queue>
using namespace std;

const int INF = 1e9;
void dijkstra(int src, int n, const vector<vector<pair<int,int>>>& adj) {
    vector<int> dist(n, INF);
    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;
    dist[src] = 0; pq.push({0, src});
    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (d > dist[u]) continue;
        for (auto [v, w] : adj[u]) {
            if (dist[u] + w < dist[v]) { dist[v] = dist[u] + w; pq.push({dist[v], v}); }
        }
    }
    for(int i = 0; i < n; i++) cout << "Dinh " << i << ": " << dist[i] << endl;
}

int main() {
    int n = 3;
    vector<vector<pair<int,int>>> adj(n);
    adj[0].push_back({1, 4}); adj[0].push_back({2, 1}); adj[2].push_back({1, 2});
    dijkstra(0, n, adj);
    return 0;
}

#include <iostream>
