struct DSU {
    vector<int> parent;
    DSU(int n) : parent(n) { for (int i = 0; i < n; i++) parent[i] = i; }
    int find(int u) {
        return (parent[u] == u) ? u : (parent[u] = find(parent[u])); // Nen duong di
    }
    void unite(int u, int v) {
        u = find(u); v = find(v);
        if (u != v) parent[u] = v;
    }
};

int main() {
    DSU dsu(5);
    dsu.unite(0, 1); dsu.unite(1, 2);
    cout << (dsu.find(0) == dsu.find(2) ? "Cung nhom" : "Khac nhom") << endl;
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

struct SegTree {
    int n; vector<int> tree;
    SegTree(int n) : n(n), tree(4 * n, 0) {}
    void update(int node, int start, int end, int idx, int val) {
        if (start == end) { tree[node] = val; return; }
        int mid = (start + end) / 2;
        if (idx <= mid) update(2 * node, start, mid, idx, val);
        else update(2 * node + 1, mid + 1, end, idx, val);
        tree[node] = tree[2 * node] + tree[2 * node + 1];
    }
    int query(int node, int start, int end, int l, int r) {
        if (r < start || end < l) return 0;
        if (l <= start && end <= r) return tree[node];
        int mid = (start + end) / 2;
        return query(2 * node, start, mid, l, r) + query(2 * node + 1, mid + 1, end, l, r);
    }
};

int main() {
    SegTree st(4);
    st.update(1, 0, 3, 0, 10); st.update(1, 0, 3, 1, 20); st.update(1, 0, 3, 2, 30);
    cout << "Tong doan [0, 2]: " << st.query(1, 0, 3, 0, 2) << endl; // In ra: 60
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

int countQueens = 0;
bool cols[20], diag1[40], diag2[40];

void solve(int row, int n) {
    if (row == n) { countQueens++; return; }
    for (int col = 0; col < n; col++) {
        if (!cols[col] && !diag1[row - col + n] && !diag2[row + col]) {
            cols[col] = diag1[row - col + n] = diag2[row + col] = true;
            solve(row + 1, n);
            cols[col] = diag1[row - col + n] = diag2[row + col] = false; // Backtrack
        }
    }
}

int main() {
    solve(0, 8);
    cout << "So cach xep 8 quan hau: " << countQueens << endl; // In ra: 92
    return 0;
}

#include <iostream>
