#include <algorithm>
using namespace std;

int lengthOfLIS(const vector<int>& nums) {
    vector<int> tail;
    for (int x : nums) {
        auto it = lower_bound(tail.begin(), tail.end(), x);
        if (it == tail.end()) tail.push_back(x);
        else *it = x;
    }
    return tail.size();
}

int main() {
    vector<int> a = {10, 9, 2, 5, 3, 7, 101, 18};
    cout << "Do dai LIS: " << lengthOfLIS(a) << endl; // In ra: 4 (2, 3, 7, 101)
    return 0;
}

